mapper.select:
SELECT ao.id, ao.adjustment_no, ao.adjustment_type, ao.warehouse_id, w.warehouse_name, ao.erp_tenant_id, t.tenant_name AS owner_name, t.parent_wms_tenant_id AS wms_tenant_id, op.tenant_name AS operator_name, ao.adjustment_date, ao.order_status, ao.adjustment_reason, ao.reject_reason, ao.confirm_time, ao.create_time FROM wms_adjustment_order ao LEFT JOIN wms_warehouse w ON ao.warehouse_id = w.id LEFT JOIN sys_tenant t ON t.id = ao.erp_tenant_id LEFT JOIN sys_tenant op ON op.id = t.parent_wms_tenant_id
AND ao.deleted = 0
AND ao.adjustment_no LIKE CONCAT('%', #{qo.adjustmentNo}, '%')
AND ao.warehouse_id = #{qo.warehouseId}
AND ao.erp_tenant_id = #{qo.erpTenantId}
AND t.parent_wms_tenant_id = #{qo.wmsTenantId}
AND ao.order_status = #{qo.orderStatus}
AND ao.adjustment_date >= #{qo.adjustmentDateStart}
AND ao.adjustment_date <= #{qo.adjustmentDateEnd}
ORDER BY ao.create_time DESC

SELECT adjustment_order_id AS adjustmentOrderId, COUNT(*) AS skuCount, COALESCE(SUM(quantity), 0) AS totalQuantity FROM wms_adjustment_order_item WHERE adjustment_order_id IN
#{id}
GROUP BY adjustment_order_id
